intfalsefileperms stringfilename
Функция возвращает информацию о правах доступа на файл.

  &reftitle.examples;



    Пример вывода прав доступа в восьмеричном представлении


<?php

echo substr(sprintf('%o', fileperms('/tmp')), -4);
echo substr(sprintf('%o', fileperms('/etc/passwd')), -4);


    &example.outputs;


1777
0644




    Пример вывода полных прав доступа


<?php

$perms = fileperms('/etc/passwd');

switch ($perms & 0xF000) {
    case 0x1000: $info = 'p'; break; // FIFO-канал
    case 0x2000: $info = 'c'; break; // символьное устройство
    case 0x4000: $info = 'd'; break; // каталог
    case 0x6000: $info = 'b'; break; // блочное устройство
    case 0x8000: $info = '-'; break; // стандартный файл
    case 0xA000: $info = 'l'; break; // символическая ссылка (доступна при вызове функции lstat)
    case 0xC000: $info = 's'; break; // сокет

    // Неизвестный
    default: $info = 'u';
}

// Владелец
$setuid = $perms & 0x0800;
$info .= (($perms & 0x0100) ? 'r' : '-');
$info .= (($perms & 0x0080) ? 'w' : '-');
$info .= (($perms & 0x0040) ? ($setuid ? 's' : 'x') : ($setuid ? 'S' : '-'));

// Группа
$setgid = $perms & 0x0400;
$info .= (($perms & 0x0020) ? 'r' : '-');
$info .= (($perms & 0x0010) ? 'w' : '-');
$info .= (($perms & 0x0008) ? ($setgid ? 's' : 'x') : ($setgid ? 'S' : '-'));

// Остальные
$sticky = $perms & 0x0200;
$info .= (($perms & 0x0004) ? 'r' : '-');
$info .= (($perms & 0x0002) ? 'w' : '-');
$info .= (($perms & 0x0001) ? ($sticky ? 't' : 'x') : ($sticky ? 'T' : '-'));

echo $info;


    &example.outputs;


-rw-r--r--
